import lzma, bz2, zlib

_FILTERS = [{"id": lzma.FILTER_LZMA2, "preset": 9 | lzma.PRESET_EXTREME, "lc": 4, "lp": 0, "pb": 0}]


def _cands(data):
    yield b"\x01" + lzma.compress(data, format=lzma.FORMAT_RAW, filters=_FILTERS)
    yield b"\x02" + bz2.compress(data, 9)
    yield b"\x03" + zlib.compress(data, 9)
    yield b"\x00" + data


def compress(data: bytes) -> bytes:
    return min(_cands(data), key=len)


def decompress(blob: bytes) -> bytes:
    tag, body = blob[0], blob[1:]
    if tag == 1:
        return lzma.decompress(body, format=lzma.FORMAT_RAW, filters=_FILTERS)
    if tag == 2:
        return bz2.decompress(body)
    if tag == 3:
        return zlib.decompress(body)
    return body
